                    double s = t * c;
                    for (int i = 0; i < n; i++) {
                        double aip = a[i][p1], aiq = a[i][q1];
                        a[i][p1] = c * aip - s * aiq;
                        a[i][q1] = s * aip + c * aiq;
                    }
                    for (int i = 0; i < n; i++) {
                        double api = a[p1][i], aqi = a[q1][i];
