import java.util.*;
public class Main {
    static int[] featureOf(double[] signal, int L) {
        int m = L / 2 - 1;
        int[] ks = new int[m];
        double[] mag = new double[m];
        for (int idx = 0; idx < m; idx++) {
            int kk = idx + 1; ks[idx] = kk;
            double re = 0, im = 0;
            for (int nn = 0; nn < L; nn++) { double ang = 2.0 * Math.PI * kk * nn / L; re += signal[nn] * Math.cos(ang); im += -signal[nn] * Math.sin(ang); }
            mag[idx] = Math.sqrt(re * re + im * im);
        }
        Integer[] ord = new Integer[m];
        for (int i = 0; i < m; i++) ord[i] = i;
        final double[] mg = mag; final int[] kks = ks;
        Arrays.sort(ord, (a, b) -> { int c = Double.compare(mg[b], mg[a]); if (c != 0) return c; return Integer.compare(kks[a], kks[b]); });
        return new int[]{ks[ord[0]], ks[ord[1]], ks[ord[2]]};
    }
    static long sq(int[] a, int[] b) { long s = 0; for (int t = 0; t < 3; t++) { long d = (long) a[t] - b[t]; s += d * d; } return s; }
    static long bankerRound(long num, long den) { long q = num / den; long r = num % den; long twice = 2 * r; if (twice < den) return q; if (twice > den) return q + 1; return (q % 2 == 0) ? q : q + 1; }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), L = sc.nextInt(), K = sc.nextInt();
        double[][] signals = new double[N][L];
        for (int i = 0; i < N; i++) for (int j = 0; j < L; j++) signals[i][j] = sc.nextDouble();
        int[] init = new int[K];
        for (int i = 0; i < K; i++) init[i] = sc.nextInt();
        int[][] features = new int[N][3];
        for (int i = 0; i < N; i++) features[i] = featureOf(signals[i], L);
        int[][] centers = new int[K][3];
        for (int c = 0; c < K; c++) centers[c] = features[init[c]].clone();
        for (int iter = 0; iter < 100; iter++) {
            List<List<Integer>> clusters = new ArrayList<>();
            for (int c = 0; c < K; c++) clusters.add(new ArrayList<>());
            for (int i = 0; i < N; i++) { int best = 0; long bd = Long.MAX_VALUE; for (int c = 0; c < K; c++) { long d = sq(features[i], centers[c]); if (d < bd) { bd = d; best = c; } } clusters.get(best).add(i); }
            int[][] nc = new int[K][3];
            for (int c = 0; c < K; c++) {
                List<Integer> cl = clusters.get(c);
                if (cl.isEmpty()) { nc[c] = centers[c].clone(); continue; }
                long cnt = cl.size();
                for (int t = 0; t < 3; t++) { long sum = 0; for (int idx : cl) sum += features[idx][t]; nc[c][t] = (int) bankerRound(sum, cnt); }
            }
            boolean same = true;
            for (int c = 0; c < K; c++) for (int t = 0; t < 3; t++) if (nc[c][t] != centers[c][t]) same = false;
            if (same) break;
            centers = nc;
        }
        int[][] sorted = centers.clone();
        Arrays.sort(sorted, (x, y) -> { if (x[0] != y[0]) return Integer.compare(x[0], y[0]); if (x[1] != y[1]) return Integer.compare(x[1], y[1]); return Integer.compare(x[2], y[2]); });
        StringBuilder sb = new StringBuilder();
        for (int c = 0; c < K; c++) { if (c > 0) sb.append((char)10); sb.append(sorted[c][0]).append(' ').append(sorted[c][1]).append(' ').append(sorted[c][2]); }
        System.out.println(sb);
    }
}

import java.util.*;
public class Main {
    static String fmt(double v) { String t = String.format(Locale.US, "%.4f", v); return t.equals("-0.0000") ? "0.0000" : t; }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt(), L = sc.nextInt(), D = sc.nextInt();
        double b = sc.nextDouble();
        int m = sc.nextInt();
        double[] x = new double[D];
        for (int i = 0; i < D; i++) x[i] = sc.nextDouble();
        double s = Math.max(1.0, (double) T / L);
        double base = b * Math.pow(s, (double) D / (D - 2));
        double[] out = new double[D];
        for (int i = 0; i < D / 2; i++) {
            double theta = m * Math.pow(base, -2.0 * i / D);
            double c = Math.cos(theta), sn = Math.sin(theta);
            int p = 2 * i;
            out[p] = x[p] * c - x[p + 1] * sn;
            out[p + 1] = x[p] * sn + x[p + 1] * c;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < D; i++) { if (i > 0) sb.append(' '); sb.append(fmt(out[i])); }
        System.out.println(sb);
    }
}

import java.util.*;
public class Main {
    static int N; static int K;
    static long[] a; static long[] pre; static long[] f; static long[] g;
    static long cost(int l, int r) {
        int mid = (l + r) / 2;
        long rep = a[mid - 1];
        return rep * (mid - l + 1) - (pre[mid] - pre[l - 1]) + (pre[r] - pre[mid]) - rep * (r - mid);
    }
    static void solve(int iL, int iR, int jL, int jR, int k) {
        if (iL > iR) return;
        int mid = (iL + iR) / 2;
        long best = Long.MAX_VALUE / 4;
        int bestj = Math.max(jL, k - 1);
        int lo = Math.max(jL, k - 1);
        int hi = Math.min(jR, mid - 1);
        for (int j = lo; j <= hi; j++) { long v = f[j] + cost(j + 1, mid); if (v < best) { best = v; bestj = j; } }
        g[mid] = best;
        solve(iL, mid - 1, jL, bestj, k);
        solve(mid + 1, iR, bestj, jR, k);
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt(); K = sc.nextInt();
        a = new long[N];
        for (int i = 0; i < N; i++) a[i] = sc.nextLong();
        pre = new long[N + 1];
        for (int i = 1; i <= N; i++) pre[i] = pre[i - 1] + a[i - 1];
        f = new long[N + 1];
        for (int i = 1; i <= N; i++) f[i] = cost(1, i);
        int kUse = Math.min(K, N);
        for (int k = 2; k <= kUse; k++) {
            g = new long[N + 1];
            Arrays.fill(g, Long.MAX_VALUE / 4);
            solve(k, N, k - 1, N - 1, k);
            f = g;
        }
        System.out.println(f[N]);
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), V = sc.nextInt(), B = sc.nextInt();
        double lam = sc.nextDouble();
        double base = 0.0;
        double[] f = new double[B + 1];
        double[] g = new double[B + 1];
        for (int it = 0; it < N; it++) {
            double[] z = new double[V];
            for (int j = 0; j < V; j++) z[j] = sc.nextDouble();
            int y = sc.nextInt(); int c = sc.nextInt();
            double mx = Double.NEGATIVE_INFINITY;
            for (double v : z) if (v > mx) mx = v;
            double sum = 0;
            double[] exps = new double[V];
            for (int j = 0; j < V; j++) { exps[j] = Math.exp(z[j] - mx); sum += exps[j]; }
            double ce = -(z[y] - mx) + Math.log(sum);
            double H = 0;
            for (int j = 0; j < V; j++) { double p = exps[j] / sum; if (p > 0) H -= p * Math.log(p); }
            base += ce;
            for (int bb = B; bb >= c; bb--) { double cand = f[bb - c] + ce; if (cand > f[bb]) { f[bb] = cand; g[bb] = g[bb - c] + H; } }
        }
        double total = base + lam * g[B];
        System.out.println(String.format(Locale.US, "%.2f", total));
    }
}

