    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        long eps = fs.nextLong();
        int minPts = fs.nextInt();
        long[] xs = new long[n];
        long[] ys = new long[n];
        for (int i = 0; i < n; i++) {
            xs[i] = fs.nextLong();
            ys[i] = fs.nextLong();
        }
        long[] count = new long[n];
        Arrays.fill(count, 1);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (Math.abs(xs[i] - xs[j]) + Math.abs(ys[i] - ys[j]) <= eps) {
                    count[i]++;
                    count[j]++;
                }
            }
        }
        boolean[] isCore = new boolean[n];
        List<Integer> coreIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            isCore[i] = count[i] >= minPts;
            if (isCore[i]) coreIndices.add(i);
        }
        int[] answer = new int[n];
        Arrays.fill(answer, 2);
        for (int i = 0; i < n; i++) {
            if (isCore[i]) {
                answer[i] = 0;
                continue;
            }
            for (int j : coreIndices) {
                if (Math.abs(xs[i] - xs[j]) + Math.abs(ys[i] - ys[j]) <= eps) {
                    answer[i] = 1;
                    break;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
