        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        long[] progress = new long[n];
        long[] cost = new long[n];
        for (int i = 0; i < n; i++) {
            progress[i] = fs.nextLong();
            cost[i] = fs.nextLong();
        }
        long INF = Long.MAX_VALUE / 4;
        long[] best = new long[100];
        long[] second = new long[100];
        int[] bestLast = new int[100];
        Arrays.fill(best, INF);
        Arrays.fill(second, INF);
        Arrays.fill(bestLast, -1);
        best[0] = 0;
        second[0] = 0;
        long answer = INF;
        for (int current = 0; current < 100; current++) {
            if (best[current] == INF) continue;
            for (int agent = 0; agent < n; agent++) {
                long base;
                if (agent == bestLast[current]) base = second[current];
                else base = best[current];
                if (base == INF) continue;
                long newCost = base + cost[agent];
                long nextProgress = current + progress[agent];
                if (nextProgress >= 100) {
                    answer = Math.min(answer, newCost);
                    continue;
                }
                int np = (int) nextProgress;
                if (newCost < best[np]) {
                    if (bestLast[np] == agent) {
                        best[np] = newCost;
                    } else {
                        second[np] = best[np];
                        best[np] = newCost;
                        bestLast[np] = agent;
                    }
                } else if (bestLast[np] != agent && newCost < second[np]) {
                    second[np] = newCost;
                }
            }
        }
        System.out.println(answer == INF ? -1 : answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static double[] merge(double[] left, double[] right) {
        if (left == null) return right;
        if (right == null) return left;
        double maximum = Math.max(left[0], right[0]);
        double ls = Math.exp(left[0] - maximum);
        double rs = Math.exp(right[0] - maximum);
        return new double[]{maximum, left[1] * ls + right[1] * rs, left[2] * ls + right[2] * rs};
    }

    static double[] query(double[][] tree, int size, int left, int right) {
        left += size;
        right += size;
        double[] lr = null;
        double[] rr = null;
        while (left < right) {
            if ((left & 1) == 1) {
                lr = merge(lr, tree[left]);
                left++;
            }
            if ((right & 1) == 1) {
                right--;
                rr = merge(tree[right], rr);
            }
            left >>= 1;
            right >>= 1;
        }
        return merge(lr, rr);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int blockCount = Integer.parseInt(t);
        int queryCount = fs.nextInt();
        double[][] blocks = new double[blockCount][];
        for (int i = 0; i < blockCount; i++) {
            blocks[i] = new double[]{fs.nextDouble(), fs.nextDouble(), fs.nextDouble()};
        }
        int size = 1;
        while (size < blockCount) size <<= 1;
        double[][] tree = new double[2 * size][];
        for (int i = 0; i < blockCount; i++) tree[size + i] = blocks[i];
        for (int i = size - 1; i >= 1; i--) tree[i] = merge(tree[2 * i], tree[2 * i + 1]);
        StringBuilder sb = new StringBuilder();
        boolean firstOut = true;
        for (int q = 0; q < queryCount; q++) {
            String op = fs.next();
            if (op.equals("1")) {
                int position = fs.nextInt() - 1;
                double m = fs.nextDouble();
                double d = fs.nextDouble();
                double v = fs.nextDouble();
                int idx = size + position;
                tree[idx] = new double[]{m, d, v};
                idx >>= 1;
                while (idx >= 1) {
                    tree[idx] = merge(tree[2 * idx], tree[2 * idx + 1]);
                    idx >>= 1;
                }
            } else {
                int left = fs.nextInt() - 1;
                int right = fs.nextInt();
                double[] res = query(tree, size, left, right);
                double denom = res[1];
                double numer = res[2];
                if (!firstOut) sb.append(NL);
                firstOut = false;
                sb.append(String.format(Locale.US, "%.6f", numer / denom));
            }
        }
        System.out.print(sb);
    }
}

