    static boolean feasible(long[] weights, long cap, int k) {
        int segments = 1;
        long current = 0;
        for (long w : weights) {
            if (current + w <= cap) {
                current += w;
            } else {
                segments++;
                current = w;
                if (segments > k) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        long[] weights = new long[n];
        for (int i = 0; i < n; i++) weights[i] = fs.nextLong();
        int k = fs.nextInt();
        long left = 0;
        long right = 0;
        for (long w : weights) {
            left = Math.max(left, w);
            right += w;
        }
        while (left < right) {
            long mid = (left + right) / 2;
            if (feasible(weights, mid, k)) right = mid;
            else left = mid + 1;
        }
        System.out.println(left);
    }
}

import java.io.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    static final int QMAX = 127;
    static final int MAX_B = 30;

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Fraction {
        BigInteger num;
        BigInteger den;
        Fraction(BigInteger n, BigInteger d) {
            if (d.signum() < 0) {
                n = n.negate();
                d = d.negate();
            }
            BigInteger g = n.gcd(d);
            if (g.signum() != 0) {
                n = n.divide(g);
                d = d.divide(g);
            }
            num = n;
            den = d;
        }
        int compareTo(Fraction o) {
            return num.multiply(o.den).compareTo(o.num.multiply(den));
        }
    }

    static Fraction parseFraction(String s) {
        BigDecimal bd = new BigDecimal(s.trim());
        BigInteger unscaled = bd.unscaledValue();
        int scale = bd.scale();
        BigInteger num;
        BigInteger den;
        if (scale >= 0) {
            num = unscaled;
            den = BigInteger.TEN.pow(scale);
        } else {
            num = unscaled.multiply(BigInteger.TEN.pow(-scale));
            den = BigInteger.ONE;
        }
        return new Fraction(num, den);
    }

    static Fraction divide(Fraction a, Fraction b) {
        return new Fraction(a.num.multiply(b.den), a.den.multiply(b.num));
    }

    static BigInteger roundHalfAway(Fraction f) {
        BigInteger n = f.num;
        BigInteger d = f.den;
        boolean neg = n.signum() < 0;
        BigInteger absN = n.abs();
        BigInteger[] qr = absN.divideAndRemainder(d);
        BigInteger q = qr[0];
        if (qr[1].shiftLeft(1).compareTo(d) >= 0) {
            q = q.add(BigInteger.ONE);
        }
        return neg ? q.negate() : q;
    }

    static class ColumnResult {
        long[] quantized;
        long a;
        long b;
        ColumnResult(long[] quantized, long a, long b) {
            this.quantized = quantized;
            this.a = a;
            this.b = b;
        }
    }

    static ColumnResult quantizeColumn(String[] tokens) {
        int len = tokens.length;
        Fraction[] column = new Fraction[len];
        for (int i = 0; i < len; i++) column[i] = parseFraction(tokens[i]);
        Fraction maximum = null;
        for (Fraction f : column) {
            Fraction abs = new Fraction(f.num.abs(), f.den);
            if (maximum == null || abs.compareTo(maximum) > 0) maximum = abs;
        }
        if (maximum.num.signum() == 0) {
            long[] zeros = new long[len];
            return new ColumnResult(zeros, 0, MAX_B);
        }
        Fraction scale = new Fraction(maximum.num, maximum.den.multiply(BigInteger.valueOf(QMAX)));
        long[] quantized = new long[len];
        for (int i = 0; i < len; i++) {
            quantized[i] = roundHalfAway(divide(column[i], scale)).longValue();
        }
        Long chosenB = null;
        Long chosenA = null;
        for (int b = MAX_B; b >= 0; b--) {
            Fraction scaled = new Fraction(scale.num.shiftLeft(b), scale.den);
            BigInteger av = roundHalfAway(scaled);
            if (av.signum() >= 0 && av.compareTo(BigInteger.valueOf(QMAX)) <= 0) {
                chosenB = (long) b;
                chosenA = av.longValue();
                break;
            }
        }
        if (chosenB == null) throw new RuntimeException("unrepresentable");
        return new ColumnResult(quantized, chosenA, chosenB);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int m = Integer.parseInt(t);
        int k = fs.nextInt();
        int n = fs.nextInt();
        long[][] qa = new long[m][k];
        long[] aa = new long[m];
        long[] ba = new long[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < k; j++) qa[i][j] = fs.nextInt();
            aa[i] = fs.nextInt();
            ba[i] = fs.nextInt();
        }
        ColumnResult[] cols = new ColumnResult[n];
        for (int i = 0; i < n; i++) {
            String[] toks = new String[k];
            for (int j = 0; j < k; j++) toks[j] = fs.next();
            cols[i] = quantizeColumn(toks);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) {
            StringBuilder line = new StringBuilder();
            boolean first = true;
            for (int j = 0; j < n; j++) {
                ColumnResult col = cols[j];
                long qc = 0;
                for (int x = 0; x < k; x++) qc += qa[i][x] * col.quantized[x];
                long ab = aa[i] * col.a;
                long bb = ba[i] + col.b;
                if (!first) line.append(' ');
                first = false;
                line.append(qc).append(' ').append(ab).append(' ').append(bb);
            }
            if (i > 0) sb.append(NL);
            sb.append(line);
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static String formatTwoDigits(double x) {
        BigDecimal value = BigDecimal.valueOf(x).setScale(2, RoundingMode.HALF_UP);
        if (value.compareTo(BigDecimal.ZERO) == 0) value = new BigDecimal("0.00");
        return value.toPlainString();
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int batchSize = Integer.parseInt(t);
        int n = fs.nextInt();
        int d = fs.nextInt();
        int window = fs.nextInt();
        if (batchSize < 1 || n < 1 || d < 1 || !(window >= 1 && window <= n)) {
            System.out.println(0);
            return;
        }
        double scale = Math.sqrt(d);
        StringBuilder sb = new StringBuilder();
        boolean firstLine = true;
        for (int bi = 0; bi < batchSize; bi++) {
            double[][] q = new double[n][d];
            double[][] kk = new double[n][d];
            double[][] v = new double[n][d];
            for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) q[i][j] = fs.nextDouble();
            for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) kk[i][j] = fs.nextDouble();
            for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) v[i][j] = fs.nextDouble();
            if (bi > 0) sb.append(NL);
            for (int i = 0; i < n; i++) {
                int left = Math.max(0, i - window);
                int right = Math.min(n, i + window + 1);
                int len = right - left;
                double[] scores = new double[len];
                double maximum = Double.NEGATIVE_INFINITY;
                for (int j = left; j < right; j++) {
                    double dot = 0.0;
                    for (int tt = 0; tt < d; tt++) dot += q[i][tt] * kk[j][tt];
                    scores[j - left] = dot / scale;
                    if (scores[j - left] > maximum) maximum = scores[j - left];
                }
                double[] exps = new double[len];
                double denom = 0.0;
                for (int j = 0; j < len; j++) {
                    exps[j] = Math.exp(scores[j] - maximum);
                    denom += exps[j];
                }
                if (!firstLine) sb.append(NL);
                firstLine = false;
                StringBuilder row = new StringBuilder();
                for (int tt = 0; tt < d; tt++) {
                    double numerator = 0.0;
                    for (int j = left; j < right; j++) numerator += exps[j - left] * v[j][tt];
                    double val = numerator / denom;
                    if (tt > 0) row.append(' ');
                    row.append(formatTwoDigits(val));
                }
                sb.append(row);
            }
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int isqrt(int n) {
        int r = (int) Math.sqrt((double) n);
        while ((long) (r + 1) * (r + 1) <= n) r++;
        while ((long) r * r > n) r--;
        return r;
    }

    static double[] mergeStats(double[] a, double[] b) {
        double na = a[0], ma = a[1], m2a = a[2];
        double nb = b[0], mb = b[1], m2b = b[2];
        if (na == 0) return b;
        if (nb == 0) return a;
        double delta = mb - ma;
        double n = na + nb;
        double mean = ma + delta * nb / n;
        double m2 = m2a + m2b + delta * delta * na * nb / n;
        return new double[]{n, mean, m2};
    }

    static double[] addValue(double[] stat, double x) {
        double n = stat[0];
        double mean = stat[1];
        double m2 = stat[2];
        double n2 = n + 1;
        double delta = x - mean;
        double mean2 = mean + delta / n2;
        return new double[]{n2, mean2, m2 + delta * (x - mean2)};
    }

    static double[] cleanValues(int[] ts, int[] raw, int[] quality) {
        int n = raw.length;
        int[] previous = new int[n];
        int[] following = new int[n];
        int last = -1;
        for (int i = 0; i < n; i++) {
            previous[i] = last;
            if (quality[i] == 0) last = i;
        }
        last = -1;
        for (int i = n - 1; i >= 0; i--) {
            following[i] = last;
            if (quality[i] == 0) last = i;
        }
        double[] values = new double[n];
        for (int i = 0; i < n; i++) values[i] = (double) raw[i];
        for (int i = 0; i < n; i++) {
            if (quality[i] != 2) continue;
            int left = previous[i];
            int right = following[i];
            if (left != -1 && right != -1) {
                double ratio = (double) (ts[i] - ts[left]) / (ts[right] - ts[left]);
                values[i] = raw[left] + (raw[right] - raw[left]) * ratio;
            } else if (left != -1) {
                values[i] = (double) raw[left];
            } else if (right != -1) {
                values[i] = (double) raw[right];
            }
        }
        return values;
    }

    static double[] rangeStats(double[] values, double[][] blockStats, int blockSize, int left, int right) {
        double[] stat = new double[]{0, 0.0, 0.0};
        while (left <= right && left % blockSize != 0) {
            stat = addValue(stat, values[left]);
            left++;
        }
        while (left + blockSize - 1 <= right) {
            stat = mergeStats(stat, blockStats[left / blockSize]);
            left += blockSize;
        }
        while (left <= right) {
            stat = addValue(stat, values[left]);
            left++;
        }
        return stat;
    }

    static double[] smoothValues(double[] values, int window, double threshold) {
        int n = values.length;
        int blockSize = Math.max(1, isqrt(n));
        int blockCount = (n + blockSize - 1) / blockSize;
        double[][] blockStats = new double[blockCount][];
        for (int s = 0; s < n; s += blockSize) {
            double[] stat = new double[]{0, 0.0, 0.0};
            for (int i = s; i < Math.min(n, s + blockSize); i++) stat = addValue(stat, values[i]);
            blockStats[s / blockSize] = stat;
        }
        int half = (window - 1) / 2;
        double[] result = values.clone();
        for (int i = 0; i < n; i++) {
            int left = Math.max(0, i - half);
            int right = Math.min(n - 1, i + half);
            double[] st = rangeStats(values, blockStats, blockSize, left, right);
            double count = st[0];
            double mean = st[1];
            double m2 = st[2];
            double variance = Math.max(0.0, m2 / count);
            if (Math.abs(values[i] - mean) > threshold * Math.sqrt(variance)) {
                result[i] = mean;
            }
        }
        return result;
    }

    static long score(double[] values, int[] quality) {
        double[] stat = new double[]{0, 0.0, 0.0};
        for (double x : values) stat = addValue(stat, x);
        double n = stat[0];
        double mean = stat[1];
        double m2 = stat[2];
        double sd = Math.sqrt(Math.max(0.0, m2 / n));
        double[] qw = new double[]{1.0, 0.5, 0.25};
        double denominator = 0.0;
        for (int i = 0; i < values.length; i++) denominator += qw[quality[i]] * Math.abs(values[i]);
        if (denominator == 0.0 || sd == 0.0) return 0;
        double total = 0.0;
        for (int i = 0; i < values.length; i++) {
            double weight = qw[quality[i]] * Math.abs(values[i]) / denominator;
            total += weight * Math.abs((values[i] - mean) / sd);
        }
        return (long) Math.floor(total * 100 + 0.5);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        int window = fs.nextInt();
        int threshold = fs.nextInt();
        int[] ts = new int[n];
        int[] raw = new int[n];
        int[] quality = new int[n];
        for (int i = 0; i < n; i++) {
            ts[i] = fs.nextInt();
            raw[i] = fs.nextInt();
            quality[i] = fs.nextInt();
        }
        double[] cleaned = cleanValues(ts, raw, quality);
        double[] smoothed = smoothValues(cleaned, window, (double) threshold);
        System.out.println(score(smoothed, quality));
    }
}

import java.io.*;
