    static long[] f;
    static long countStages(long cap) {
        long stages = 1;
        long load = 0;
        for (long x : f) {
            if (load + x > cap) { stages++; load = 0; }
            load += x;
        }
        return stages;
    }
    public static void main(String[] args) {
        In in = new In();
        int n = in.ni();
        int k = in.ni();
        f = new long[n];
        long lo = Long.MIN_VALUE, hi = 0;
        for (int i = 0; i < n; i++) { f[i] = in.nl(); if (f[i] > lo) lo = f[i]; hi += f[i]; }
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (countStages(mid) <= k) hi = mid; else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class In {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() { while (!st.hasMoreTokens()) { String l=null; try { l=br.readLine(); } catch (IOException e) { throw new RuntimeException(e); } if (l==null) return null; st=new StringTokenizer(l); } return st.nextToken(); }
        int ni() { return Integer.parseInt(next()); }
        long nl() { return Long.parseLong(next()); }
    }
    static class Cand { int idx; long score; Cand(int i, long s) { idx=i; score=s; } }
    public static void main(String[] args) {
        In in = new In();
        int L = in.ni(), D = in.ni(), G = in.ni(), W = in.ni(), T = in.ni();
        int[] globalList = new int[G];
        for (int i = 0; i < G; i++) globalList[i] = in.ni();
        boolean[] isGlobal = new boolean[L];
        for (int p : globalList) isGlobal[p] = true;
        int size = L * D;
        long[] q = new long[size];
        long[] k = new long[size];
        long[] v = new long[size];
        for (int i = 0; i < size; i++) q[i] = in.nl();
        for (int i = 0; i < size; i++) k[i] = in.nl();
        for (int i = 0; i < size; i++) v[i] = in.nl();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < L; i++) {
            int[] cand;
            if (isGlobal[i]) {
                cand = new int[L];
                for (int j = 0; j < L; j++) cand[j] = j;
            } else {
                int lo = Math.max(0, i - W), hi = Math.min(L - 1, i + W);
                List<Integer> list = new ArrayList<>();
                for (int j = lo; j <= hi; j++) list.add(j);
                for (int p : globalList) if (p < lo || p > hi) list.add(p);
                cand = new int[list.size()];
                for (int j = 0; j < cand.length; j++) cand[j] = list.get(j);
            }
            List<Cand> kept = new ArrayList<>();
            for (int c : cand) {
                long s = 0;
                int base = c * D, qbase = i * D;
                for (int d = 0; d < D; d++) s += k[base + d] * q[qbase + d];
                if (s > 0) kept.add(new Cand(c, s));
            }
            kept.sort(new Comparator<Cand>() {
                public int compare(Cand a, Cand b) { if (a.score != b.score) return Long.compare(b.score, a.score); return Integer.compare(a.idx, b.idx); }
            });
            int take = Math.min(T, kept.size());
            if (take <= 0) {
                for (int d = 0; d < D; d++) { if (d > 0) out.append(' '); out.append(0); }
                out.append((char)10);
                continue;
            }
            long[] res = new long[D];
            for (int t = 0; t < take; t++) { Cand c = kept.get(t); int base = c.idx * D; for (int d = 0; d < D; d++) res[d] += c.score * v[base + d]; }
            for (int d = 0; d < D; d++) { if (d > 0) out.append(' '); out.append(res[d]); }
            out.append((char)10);
        }
        System.out.print(out.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class In {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() { while (!st.hasMoreTokens()) { String l=null; try { l=br.readLine(); } catch (IOException e) { throw new RuntimeException(e); } if (l==null) return null; st=new StringTokenizer(l); } return st.nextToken(); }
        int ni() { return Integer.parseInt(next()); }
        long nl() { return Long.parseLong(next()); }
    }
    public static void main(String[] args) {
        In in = new In();
        int n = in.ni();
        int budget = in.ni();
        long[] forward = new long[n];
        for (int i = 0; i < n; i++) forward[i] = in.nl();
        long[] memory = new long[n];
        for (int i = 0; i < n; i++) memory[i] = in.nl();
        long[] prefix = new long[n + 1];
        long[] weighted = new long[n + 1];
        for (int i = 1; i <= n; i++) { prefix[i] = prefix[i - 1] + forward[i - 1]; weighted[i] = weighted[i - 1] + (long) i * forward[i - 1]; }
        final long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[n][budget + 1];
        for (int i = 0; i < n; i++) Arrays.fill(dp[i], INF);
        dp[0][0] = 0;
        long answer = INF;
        for (int end = 1; end <= n; end++) {
            long need = end < n ? memory[end - 1] : 0;
            if (need > budget) continue;
            for (int start = 0; start < end; start++) {
                long cost = (long) end * (prefix[end - 1] - prefix[start]) - (weighted[end - 1] - weighted[start]);
                long[] previous = dp[start];
                if (end == n) {
                    long minPrev = INF;
                    for (int u = 0; u <= budget; u++) if (previous[u] < minPrev) minPrev = previous[u];
                    if (minPrev < INF) { long cand = minPrev + cost; if (cand < answer) answer = cand; }
                } else {
                    long[] current = dp[end];
                    int lim = (int)(budget - need);
                    for (int used = 0; used <= lim; used++) {
                        if (previous[used] >= INF) continue;
                        long cand = previous[used] + cost;
                        int idx = used + (int) need;
                        if (cand < current[idx]) current[idx] = cand;
                    }
                }
            }
        }
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;
import java.util.Locale;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) { return; }
        String[] parts = line.trim().split(";");
        String[] timeStrs = parts[0].split(",");
        int n = timeStrs.length;
        long[] times = new long[n];
        for (int i = 0; i < n; i++) times[i] = Long.parseLong(timeStrs[i].trim());
        int k = Integer.parseInt(parts[1].trim());
        double baseLr = Double.parseDouble(parts[2].trim());
        double decay = Double.parseDouble(parts[3].trim());
        int size = 1 << n;
        long[] subsetSum = new long[size];
        int[] count = new int[size];
        for (int mask = 1; mask < size; mask++) {
            int low = mask & -mask;
            int bit = Integer.numberOfTrailingZeros(low);
            subsetSum[mask] = subsetSum[mask ^ low] + times[bit];
            count[mask] = count[mask ^ low] + 1;
        }
        final double INF = Double.POSITIVE_INFINITY;
        double[] previous = new double[size];
        Arrays.fill(previous, INF);
        previous[0] = 0;
        for (int groups = 1; groups <= k; groups++) {
            double[] current = new double[size];
            Arrays.fill(current, INF);
            for (int mask = 1; mask < size; mask++) {
                if (!(groups <= count[mask] && count[mask] <= n - k + groups)) continue;
                int low = mask & -mask;
                int rest = mask ^ low;
                int sub = rest;
                while (true) {
                    int group = sub | low;
                    double cand = Math.max(previous[mask ^ group], (double) subsetSum[group]);
                    if (cand < current[mask]) current[mask] = cand;
                    if (sub == 0) break;
                    sub = (sub - 1) & rest;
                }
            }
            previous = current;
        }
        double bestTime = previous[size - 1];
        double[] cost = new double[size];
        Arrays.fill(cost, INF);
        for (int mask = 0; mask < size; mask++) {
            long load = subsetSum[mask];
            if (load <= bestTime) cost[mask] = load * Math.pow(decay, bestTime - load);
        }
        previous = new double[size];
        Arrays.fill(previous, INF);
        previous[0] = 0.0;
        for (int groups = 1; groups <= k; groups++) {
            double[] current = new double[size];
            Arrays.fill(current, INF);
            for (int mask = 1; mask < size; mask++) {
                if (!(groups <= count[mask] && count[mask] <= n - k + groups)) continue;
                int low = mask & -mask;
                int rest = mask ^ low;
                int sub = rest;
                while (true) {
                    int group = sub | low;
                    double cand = previous[mask ^ group] + cost[group];
                    if (cand < current[mask]) current[mask] = cand;
                    if (sub == 0) break;
                    sub = (sub - 1) & rest;
                }
            }
            previous = current;
        }
        double answer = previous[size - 1] * baseLr;
        String bt;
        if (!Double.isInfinite(bestTime) && bestTime == Math.floor(bestTime)) bt = String.valueOf((long) bestTime) + ".0";
        else bt = String.valueOf(bestTime);
        System.out.println(bt + ";" + String.format(Locale.US, "%.4f", answer));
    }
}

import java.io.*;
import java.util.*;
import java.util.Locale;

public class Main {
    static class In {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() { while (!st.hasMoreTokens()) { String l=null; try { l=br.readLine(); } catch (IOException e) { throw new RuntimeException(e); } if (l==null) return null; st=new StringTokenizer(l); } return st.nextToken(); }
        int ni() { return Integer.parseInt(next()); }
        double nd() { return Double.parseDouble(next()); }
    }
    static double median(double[] arr) {
        double[] c = arr.clone();
        Arrays.sort(c);
        int m = c.length;
        if (m % 2 == 1) return c[m / 2];
        return (c[m / 2 - 1] + c[m / 2]) / 2.0;
    }
    public static void main(String[] args) {
        In in = new In();
        int n = in.ni(), d = in.ni(), k = in.ni();
        double[][] points = new double[n][d];
        for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) points[i][j] = in.nd();
        double[][] centers = new double[k][d];
        for (int i = 0; i < k; i++) centers[i] = points[i].clone();
        int[] labels = new int[n];
        for (int iter = 0; iter < 100; iter++) {
            for (int i = 0; i < n; i++) {
                int best = -1;
                double bestD = 0;
                for (int j = 0; j < k; j++) {
                    double s = 0;
                    for (int ax = 0; ax < d; ax++) s += Math.abs(points[i][ax] - centers[j][ax]);
                    if (best == -1 || s < bestD) { bestD = s; best = j; }
                }
                labels[i] = best;
            }
            double[][] updated = new double[k][d];
            for (int j = 0; j < k; j++) {
                List<Integer> members = new ArrayList<>();
                for (int i = 0; i < n; i++) if (labels[i] == j) members.add(i);
                if (members.isEmpty()) { updated[j] = centers[j].clone(); continue; }
                double[] vals = new double[members.size()];
                for (int ax = 0; ax < d; ax++) {
                    for (int t = 0; t < members.size(); t++) vals[t] = points[members.get(t)][ax];
                    updated[j][ax] = median(vals);
                }
            }
            double shift = 0;
            for (int j = 0; j < k; j++) for (int ax = 0; ax < d; ax++) shift += Math.abs(updated[j][ax] - centers[j][ax]);
            centers = updated;
            if (shift < 1e-4) break;
        }
        double inertia = 0;
        for (int i = 0; i < n; i++) for (int ax = 0; ax < d; ax++) inertia += Math.abs(points[i][ax] - centers[labels[i]][ax]);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) { if (i > 0) sb.append(' '); sb.append(labels[i]); }
        sb.append((char)10);
        for (int j = 0; j < k; j++) {
            StringBuilder line = new StringBuilder();
            for (int ax = 0; ax < d; ax++) { if (ax > 0) line.append(' '); line.append(String.format(Locale.US, "%.6f", centers[j][ax])); }
            sb.append(line).append((char)10);
        }
        sb.append(String.format(Locale.US, "%.6f", inertia)).append((char)10);
        System.out.print(sb.toString());
    }
}

import java.io.*;
