 static final long NEG=Long.MIN_VALUE/4;
 static long[] leftWindowMax(long[] a,int d){
  int n=a.length;long[] result=new long[n];Arrays.fill(result,NEG);
  int[] dq=new int[n];int head=0,tail=0;
  for(int i=0;i<n;i++){
   while(head<tail&&dq[head]<i-d)head++;
   if(head<tail)result[i]=a[dq[head]];
   while(head<tail&&a[dq[tail-1]]<=a[i])tail--;
   dq[tail++]=i;
  }
  return result;
 }
