 static final long MOD=1000000007L;
 static long pathWeightSum(long n){
  long last=n-1;long answer=0;
  for(int t=0;t<=60;t++){
   long first=(1L<<t)-1;
   if(first>last)break;
   long step=1L<<(t+1);
   long count=(last-first)/step+1;
   if(t==0)count-=1;
   answer=(answer+(count%MOD)*((step-1)%MOD))%MOD;
  }
  return answer;
 }
 public static void main(String[] args)throws IOException{
  FS fs=new FS();
  int t=fs.ni();StringBuilder out=new StringBuilder();char NL=(char)10;
  for(int tc=0;tc<t;tc++){long n=fs.nl();out.append(pathWeightSum(n));if(tc<t-1)out.append(NL);}
  System.out.print(out);
 }
