 static class FS{byte[] b=new byte[1<<16];int p=0,n=0;InputStream in=System.in;int r()throws IOException{if(p>=n){n=in.read(b);p=0;if(n<=0)return -1;}return b[p++];}long nl()throws IOException{int c;do{c=r();}while(c!=-1&&c<=' ');boolean g=false;if(c=='-'){g=true;c=r();}long v=0;while(c>' '){v=v*10+(c-'0');c=r();}return g?-v:v;}int ni()throws IOException{return (int)nl();}String ns()throws IOException{int c;do{c=r();}while(c!=-1&&c<=' ');StringBuilder s=new StringBuilder();while(c>' '){s.append((char)c);c=r();}return s.toString();}}
 static int[] buildSPF(int limit){int[] spf=new int[limit+1];for(int i=0;i<=limit;i++)spf[i]=i;if(limit>=1)spf[1]=1;for(int i=2;(long)i*i<=limit;i++)if(spf[i]==i)for(long j=(long)i*i;j<=limit;j+=i)if(spf[(int)j]==(int)j)spf[(int)j]=i;return spf;}
 static ArrayList<Integer> divisors(int v,int[] spf){
  ArrayList<Integer> divs=new ArrayList<>();
  if(v<1)return divs;
  divs.add(1);int x=v;
  while(x>1){int p=spf[x];int cnt=0;while(x%p==0){x/=p;cnt++;}int size=divs.size();int mult=1;for(int e=1;e<=cnt;e++){mult*=p;for(int k=0;k<size;k++)divs.add(divs.get(k)*mult);}}
  return divs;
 }
 static long maxEnabled(int[] ps,int[] spf){
  HashMap<Integer,Integer> freq=new HashMap<>();
  for(int v:ps)freq.merge(v,1,Integer::sum);
  HashMap<Integer,Long> cnt=new HashMap<>();
  for(Map.Entry<Integer,Integer> e:freq.entrySet()){
   int v=e.getKey();long f=e.getValue();
   for(int d:divisors(v,spf))cnt.merge(d,f,Long::sum);
  }
  long best=0;
  for(Map.Entry<Integer,Long> e:cnt.entrySet()){long val=Math.min(e.getKey(),e.getValue());if(val>best)best=val;}
  return best;
 }
 public static void main(String[] args)throws IOException{
  FS fs=new FS();
  int t=fs.ni();
  int[][] groups=new int[t][];int limit=0;
  for(int g=0;g<t;g++){int c=fs.ni();int[] arr=new int[c];for(int i=0;i<c;i++){arr[i]=fs.ni();if(arr[i]>limit)limit=arr[i];}groups[g]=arr;}
  int[] spf=buildSPF(limit);
  StringBuilder out=new StringBuilder();
  for(int g=0;g<t;g++){if(g>0)out.append(' ');out.append(maxEnabled(groups[g],spf));}
  System.out.print(out);
 }
}

