import java.util.*;

public class Main {
    static long prefixXor(long n) {
        if (n < 0) return 0;
        long r = n % 4;
        if (r == 0) return n;
        if (r == 1) return 1;
        if (r == 2) return n + 1;
        return 0;
    }

    static long minRight(long x, long z) {
        long target = z ^ prefixXor(x - 1);
        long best = -1;
        long[] cand = {x, x + 1, x + 2, x + 3, target - 1, target};
        for (long y : cand) {
            if (y >= x && prefixXor(y) == target) {
                if (best == -1 || y < best) best = y;
            }
        }
        return best;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        StringTokenizer st = new StringTokenizer(line);
        long x = Long.parseLong(st.nextToken());
        long z = Long.parseLong(st.nextToken());
        System.out.println(minRight(x, z));
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long LIMIT = 10000000000000000L;
    static final int MAX_X = 2500;

    static long buildMin(int length, long s) {
        long num = 0;
        for (int i = 0; i < length; i++) {
            int rest = length - i - 1;
            long d = (i == 0) ? 1 : 0;
            while (s - d > 9L * rest) {
                d++;
            }
            num = num * 10 + d;
            s -= d;
        }
        return num;
    }

    static long minNumber(int x) {
        for (int length = 1; length <= 17; length++) {
            if (x % length != 0) continue;
            long s = x / length;
            if (s > 9L * length) continue;
            long num = buildMin(length, s);
            if (num <= LIMIT) return num;
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        int t = Integer.parseInt(line.trim());
        long[] answers = new long[MAX_X + 1];
        for (int x = 1; x <= MAX_X; x++) answers[x] = minNumber(x);
        for (int i = 0; i < t; i++) {
            String s = br.readLine();
            while (s != null && s.trim().isEmpty()) s = br.readLine();
            int x = Integer.parseInt(s.trim());
            System.out.println(answers[x]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long INF = Long.MAX_VALUE / 4;

    static long[] dijkstra(List<List<long[]>> graph, int source) {
        int n = graph.size() - 1;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        dist[source] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(new Comparator<long[]>() {
            public int compare(long[] a, long[] b) { return Long.compare(a[0], b[0]); }
        });
        pq.add(new long[]{0, source});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int node = (int) cur[1];
            if (d != dist[node]) continue;
            for (long[] e : graph.get(node)) {
                int nxt = (int) e[0];
                long w = e[1];
                long nd = d + w;
                if (nd < dist[nxt]) {
                    dist[nxt] = nd;
                    pq.add(new long[]{nd, nxt});
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String l;
        while ((l = br.readLine()) != null) { all.append(l); all.append(' '); }
        StringTokenizer st = new StringTokenizer(all.toString());
        if (!st.hasMoreTokens()) return;
        int n = Integer.parseInt(st.nextToken());
        int directedCount = Integer.parseInt(st.nextToken());
        int undirectedCount = Integer.parseInt(st.nextToken());
        int station = Integer.parseInt(st.nextToken());
        List<List<long[]>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());
        for (int i = 0; i < directedCount; i++) {
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            long w = Long.parseLong(st.nextToken());
            graph.get(u).add(new long[]{v, w});
        }
        for (int i = 0; i < undirectedCount; i++) {
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            long w = Long.parseLong(st.nextToken());
            graph.get(u).add(new long[]{v, w});
            graph.get(v).add(new long[]{u, w});
        }
        long handTime = Long.parseLong(st.nextToken());
        long lockerTime = Long.parseLong(st.nextToken());
        int deliveryCount = Integer.parseInt(st.nextToken());
        int[] destinations = new int[deliveryCount];
        Set<Integer> useful = new LinkedHashSet<>();
        useful.add(station);
        for (int i = 0; i < deliveryCount; i++) {
            destinations[i] = Integer.parseInt(st.nextToken());
            useful.add(destinations[i]);
        }
        Map<Integer, long[]> distances = new HashMap<>();
        for (int src : useful) distances.put(src, dijkstra(graph, src));
        long totalTime = 0;
        int current = station;
        for (int dest : destinations) {
            totalTime += distances.get(current)[dest];
            if (totalTime % 2 == 1) totalTime += handTime;
            else totalTime += lockerTime;
            current = dest;
        }
        totalTime += distances.get(current)[station];
        System.out.println(totalTime);
    }
}

import java.io.*;
