public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String l;
        while ((l = br.readLine()) != null) { all.append(l); all.append(' '); }
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        long target = Long.parseLong(st.nextToken());
        HashMap<Long, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long v = Long.parseLong(st.nextToken());
            count.put(v, count.getOrDefault(v, 0) + 1);
        }
        long answer = 0;
        for (Map.Entry<Long, Integer> e : count.entrySet()) {
            long value = e.getKey();
            int frequency = e.getValue();
            long other = target - value;
            if (!count.containsKey(other)) continue;
            if (value == other) answer += frequency - 1;
            else if (value < other) answer += Math.min(frequency, count.get(other));
        }
        System.out.println(answer);
    }
}

