import java.io.*;
import java.util.*;

public class Main {
    static class Group implements Comparable<Group> {
        int value, count;
        Group(int v, int c) { value = v; count = c; }
        public int compareTo(Group o) {
            if (count != o.count) return Integer.compare(o.count, count);
            return Integer.compare(value, o.value);
        }
    }

    static int[] rearrange(int[] a, int k) {
        int n = a.length;
        HashMap<Integer, Integer> counter = new HashMap<>();
        for (int v : a) counter.put(v, counter.getOrDefault(v, 0) + 1);
        ArrayList<Group> groups = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : counter.entrySet())
            groups.add(new Group(e.getKey(), e.getValue()));
        Collections.sort(groups);
        int frequency = groups.get(0).count;
        int tied = 0;
        for (Group g : groups) if (g.count == frequency) tied++;
        if ((long) (frequency - 1) * k + tied > n) return null;
        if (frequency == 1) {
            int[] sorted = a.clone();
            Arrays.sort(sorted);
            return sorted;
        }
        PriorityQueue<int[]> available = new PriorityQueue<>(new Comparator<int[]>() {
            public int compare(int[] x, int[] y) {
                if (x[0] != y[0]) return Integer.compare(x[0], y[0]);
                return Integer.compare(x[1], y[1]);
            }
        });
        for (Group g : groups) available.add(new int[]{-g.count, g.value});
        ArrayDeque<int[]> cooling = new ArrayDeque<>();
        ArrayList<Integer> candidate = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!cooling.isEmpty() && cooling.peekFirst()[0] <= i) {
                int[] c = cooling.pollFirst();
                available.add(new int[]{c[1], c[2]});
            }
            if (available.isEmpty()) break;
            int[] top = available.poll();
            int count = top[0];
            int value = top[1];
            candidate.add(value);
            if (count + 1 < 0) cooling.addLast(new int[]{i + k, count + 1, value});
        }
        if (candidate.size() == n) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) res[i] = candidate.get(i);
            return res;
        }
        ArrayList<ArrayList<Integer>> rows = new ArrayList<>();
        for (int i = 0; i < frequency; i++) rows.add(new ArrayList<>());
        for (int gi = 0; gi < tied; gi++) {
            int value = groups.get(gi).value;
            for (ArrayList<Integer> row : rows) row.add(value);
        }
        int rowIndex = 0;
        for (int gi = tied; gi < groups.size(); gi++) {
            int value = groups.get(gi).value;
            int count = groups.get(gi).count;
            for (int c = 0; c < count; c++) {
                rows.get(rowIndex).add(value);
                rowIndex = (rowIndex + 1) % (frequency - 1);
            }
        }
        int[] res = new int[n];
        int p = 0;
        for (ArrayList<Integer> row : rows) for (int v : row) res[p++] = v;
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String l;
        while ((l = br.readLine()) != null) { all.append(l); all.append(' '); }
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        int[] result = rearrange(a, k);
        if (result == null) {
            System.out.println(-1);
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < result.length; i++) {
                if (i > 0) sb.append(' ');
                sb.append(result[i]);
            }
            System.out.println(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    static List<String> extractQuoted(String s) {
        List<String> res = new ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == (char) 39 || c == (char) 34) {
                char q = c;
                int j = i + 1;
                StringBuilder sb = new StringBuilder();
                while (j < s.length() && s.charAt(j) != q) { sb.append(s.charAt(j)); j++; }
                res.add(sb.toString());
                i = j + 1;
            } else {
                i++;
            }
        }
        return res;
    }

    static String format3(double v) {
        BigDecimal bd = new BigDecimal(v).setScale(3, RoundingMode.HALF_EVEN);
        String s = bd.stripTrailingZeros().toPlainString();
        if (s.indexOf('.') < 0) s += ".0";
        return s;
    }

    static String[] splitWords(String s) {
        s = s.trim();
        if (s.isEmpty()) return new String[0];
        StringTokenizer st = new StringTokenizer(s);
        String[] arr = new String[st.countTokens()];
        for (int i = 0; i < arr.length; i++) arr[i] = st.nextToken();
        return arr;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String sentencesLine = br.readLine();
        String queryLine = br.readLine();
        List<String> sentences = extractQuoted(sentencesLine);
        List<String> q = extractQuoted(queryLine);
        String word = q.get(0);
        StringBuilder rest = new StringBuilder();
        boolean inQuote = false;
        char qc = 0;
        for (int i = 0; i < queryLine.length(); i++) {
            char c = queryLine.charAt(i);
            if (inQuote) { if (c == qc) inQuote = false; continue; }
            if (c == (char) 39 || c == (char) 34) { inQuote = true; qc = c; continue; }
            rest.append(c);
        }
        int idx = 0;
        StringTokenizer qt = new StringTokenizer(rest.toString(), "[],() ");
        if (qt.hasMoreTokens()) idx = Integer.parseInt(qt.nextToken());
        int n = sentences.size();
        String[][] docs = new String[n][];
        for (int i = 0; i < n; i++) docs[i] = splitWords(sentences.get(i));
        String[] target = docs[idx];
        int occurrences = 0;
        for (String w : target) if (w.equals(word)) occurrences++;
        double tf = (double) occurrences / target.length;
        int nw = 0;
        for (String[] d : docs) {
            for (String w : d) if (w.equals(word)) { nw++; break; }
        }
        double idf = Math.log((double) n / (nw + 1) + 1.0);
        System.out.println(format3(tf * idf));
    }
}

import java.io.*;
import java.util.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    static int pos = 0;
    static String src;

    static void skipWs() { while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) pos++; }

    static Object parseValue() {
        skipWs();
        char c = src.charAt(pos);
        if (c == '(') return parseSeq(')');
        if (c == '[') return parseSeq(']');
        return parseNumber();
    }

    static List<Object> parseSeq(char close) {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        if (src.charAt(pos) == close) { pos++; return list; }
        while (true) {
            list.add(parseValue());
            skipWs();
            char c = src.charAt(pos);
            if (c == ',') { pos++; continue; }
            if (c == close) { pos++; break; }
        }
        return list;
    }

    static Double parseNumber() {
        skipWs();
        int start = pos;
        if (src.charAt(pos) == '+' || src.charAt(pos) == '-') pos++;
        while (pos < src.length()) {
            char c = src.charAt(pos);
            if (Character.isDigit(c) || c == '.' || c == 'e' || c == 'E') pos++;
            else if ((c == '+' || c == '-') && pos > start && (src.charAt(pos - 1) == 'e' || src.charAt(pos - 1) == 'E')) pos++;
            else break;
        }
        return Double.parseDouble(src.substring(start, pos));
    }

    static double[][] toMatrix(Object o) {
        List<Object> rows = (List<Object>) o;
        double[][] m = new double[rows.size()][];
        for (int i = 0; i < rows.size(); i++) {
            List<Object> row = (List<Object>) rows.get(i);
            m[i] = new double[row.size()];
            for (int j = 0; j < row.size(); j++) m[i][j] = (Double) row.get(j);
        }
        return m;
    }

    static double[] toVector(Object o) {
        List<Object> v = (List<Object>) o;
        double[] a = new double[v.size()];
        for (int i = 0; i < v.size(); i++) a[i] = (Double) v.get(i);
        return a;
    }

    static double[][] matMul(double[][] A, double[][] B) {
        int n = A.length, p = B.length, m = B[0].length;
        double[][] C = new double[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                double s = 0;
                for (int k = 0; k < p; k++) s += A[i][k] * B[k][j];
                C[i][j] = s;
            }
        return C;
    }

    static double[][] addBias(double[][] M, Object b) {
        double[][] R = new double[M.length][];
        if (b instanceof Double) {
            double s = (Double) b;
            for (int i = 0; i < M.length; i++) {
                R[i] = new double[M[i].length];
                for (int j = 0; j < M[i].length; j++) R[i][j] = M[i][j] + s;
            }
        } else {
            List<Object> bl = (List<Object>) b;
            if (!bl.isEmpty() && bl.get(0) instanceof List) {
                double[][] bm = toMatrix(b);
                for (int i = 0; i < M.length; i++) {
                    R[i] = new double[M[i].length];
                    for (int j = 0; j < M[i].length; j++) R[i][j] = M[i][j] + bm[i % bm.length][0];
                }
            } else {
                double[] bv = toVector(b);
                for (int i = 0; i < M.length; i++) {
                    R[i] = new double[M[i].length];
                    for (int j = 0; j < M[i].length; j++) R[i][j] = M[i][j] + bv[j % bv.length];
                }
            }
        }
        return R;
    }

    static double sigmoid(double z) { return 1.0 / (1.0 + Math.exp(-z)); }

    static String format3(double v) {
        BigDecimal bd = new BigDecimal(v).setScale(3, RoundingMode.HALF_EVEN);
        String s = bd.stripTrailingZeros().toPlainString();
        if (s.indexOf('.') < 0) s += ".0";
        return s;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String l;
        while ((l = br.readLine()) != null) all.append(l);
        src = all.toString();
        Object root = parseValue();
        List<Object> parts = (List<Object>) root;
        double[][] W1 = toMatrix(parts.get(0));
        double[][] W2 = toMatrix(parts.get(1));
        Object b = parts.get(2);
        double[][] X = toMatrix(parts.get(3));
        double[][] Y = toMatrix(parts.get(4));
        double[][] Z1 = addBias(matMul(W1, X), b);
        for (int i = 0; i < Z1.length; i++) for (int j = 0; j < Z1[i].length; j++) Z1[i][j] = sigmoid(Z1[i][j]);
        double[][] H = addBias(matMul(W2, Z1), b);
        for (int i = 0; i < H.length; i++) for (int j = 0; j < H[i].length; j++) H[i][j] = sigmoid(H[i][j]);
        double loss = 0;
        for (int i = 0; i < H.length; i++)
            for (int j = 0; j < H[i].length; j++) {
                double h = H[i][j];
                double y = Y[i][j];
                loss += -y * Math.log(h) - (1 - y) * Math.log(1 - h);
            }
        System.out.println(format3(loss));
    }
}

