    static String num4(double v) {
        BigDecimal bd = new BigDecimal(v).setScale(4, RoundingMode.HALF_EVEN);
        String s = bd.stripTrailingZeros().toPlainString();
        if (s.indexOf('.') < 0) s += ".";
        return s;
    }

    static String readNonEmpty(BufferedReader br) throws Exception {
        String s = br.readLine();
        while (s != null && s.trim().isEmpty()) s = br.readLine();
        return s;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String xLine = readNonEmpty(br);
        String yLine = readNonEmpty(br);
        String alphaLine = readNonEmpty(br);
        String iterLine = readNonEmpty(br);
        src = xLine; pos = 0;
        double[][] X = toMatrix(parseValue());
        src = yLine; pos = 0;
        double[] y = toVector(parseValue());
        double alpha = Double.parseDouble(alphaLine.trim());
        int iters = Integer.parseInt(iterLine.trim());
        int m = X.length;
        int d = X[0].length;
        double[] theta = new double[d];
        double[] residual = new double[m];
        for (int it = 0; it < iters; it++) {
            for (int i = 0; i < m; i++) {
                double s = 0;
                for (int j = 0; j < d; j++) s += X[i][j] * theta[j];
                residual[i] = s - y[i];
            }
            double[] gradient = new double[d];
            for (int j = 0; j < d; j++) {
                double s = 0;
                for (int i = 0; i < m; i++) s += X[i][j] * residual[i];
                gradient[j] = s / m;
            }
            for (int j = 0; j < d; j++) theta[j] -= alpha * gradient[j];
        }
        StringBuilder sb = new StringBuilder("[");
        for (int j = 0; j < d; j++) {
            if (j > 0) sb.append(' ');
            sb.append(num4(theta[j]));
        }
        sb.append(']');
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int pos = 0;
    static String src;

    static void skipWs() { while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) pos++; }

    static Object parseValue() {
        skipWs();
        char c = src.charAt(pos);
        if (c == '(') return parseSeq(')');
        if (c == '[') return parseSeq(']');
        return parseNumber();
    }

    static List<Object> parseSeq(char close) {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        if (src.charAt(pos) == close) { pos++; return list; }
        while (true) {
            list.add(parseValue());
            skipWs();
            char c = src.charAt(pos);
            if (c == ',') { pos++; continue; }
            if (c == close) { pos++; break; }
        }
        return list;
    }

    static Double parseNumber() {
        skipWs();
        int start = pos;
        if (src.charAt(pos) == '+' || src.charAt(pos) == '-') pos++;
        while (pos < src.length()) {
            char c = src.charAt(pos);
            if (Character.isDigit(c) || c == '.' || c == 'e' || c == 'E') pos++;
            else if ((c == '+' || c == '-') && pos > start && (src.charAt(pos - 1) == 'e' || src.charAt(pos - 1) == 'E')) pos++;
            else break;
        }
        return Double.parseDouble(src.substring(start, pos));
    }

    static double[][] toMatrix(Object o) {
        List<Object> rows = (List<Object>) o;
        double[][] m = new double[rows.size()][];
        for (int i = 0; i < rows.size(); i++) {
            List<Object> row = (List<Object>) rows.get(i);
            m[i] = new double[row.size()];
            for (int j = 0; j < row.size(); j++) m[i][j] = (Double) row.get(j);
        }
        return m;
    }

    static double[] toVector(Object o) {
        List<Object> v = (List<Object>) o;
        double[] a = new double[v.size()];
        for (int i = 0; i < v.size(); i++) a[i] = (Double) v.get(i);
        return a;
    }

    static String readNonEmpty(BufferedReader br) throws Exception {
        String s = br.readLine();
        while (s != null && s.trim().isEmpty()) s = br.readLine();
        return s;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String xLine = readNonEmpty(br);
        String yLine = readNonEmpty(br);
        String wLine = readNonEmpty(br);
        String lrLine = readNonEmpty(br);
        String iterLine = readNonEmpty(br);
        String batchLine = readNonEmpty(br);
        String methodLine = readNonEmpty(br);
        src = xLine; pos = 0;
        double[][] X = toMatrix(parseValue());
        src = yLine; pos = 0;
        double[] y = toVector(parseValue());
        src = wLine; pos = 0;
        double[] w = toVector(parseValue());
        double learningRate = Double.parseDouble(lrLine.trim());
        int nIterations = Integer.parseInt(iterLine.trim());
        int batchSize = Integer.parseInt(batchLine.trim());
        String method;
        if (methodLine.contains("stochastic")) method = "stochastic";
        else if (methodLine.contains("mini")) method = "mini";
        else method = "batch";
        int m = X.length;
        int d = w.length;
        int step;
        if (method.equals("batch")) step = m;
        else if (method.equals("stochastic")) step = 1;
        else step = batchSize;
        for (int it = 0; it < nIterations; it++) {
            for (int start = 0; start < m; start += step) {
                int end = Math.min(start + step, m);
                int len = end - start;
                double[] residual = new double[len];
                for (int i = start; i < end; i++) {
                    double s = 0;
                    for (int j = 0; j < d; j++) s += X[i][j] * w[j];
                    residual[i - start] = s - y[i];
                }
                double[] gradient = new double[d];
                for (int j = 0; j < d; j++) {
                    double s = 0;
                    for (int i = start; i < end; i++) s += X[i][j] * residual[i - start];
                    gradient[j] = (2.0 / step) * s;
                }
                for (int j = 0; j < d; j++) w[j] -= learningRate * gradient[j];
            }
        }
        StringBuilder sb = new StringBuilder("[");
        for (int j = 0; j < d; j++) {
            if (j > 0) sb.append(' ');
            sb.append(Double.toString(w[j]));
        }
        sb.append(']');
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int[] parseInts(String s) {
        List<Integer> list = new ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (Character.isDigit(c) || (c == '-' && i + 1 < s.length() && Character.isDigit(s.charAt(i + 1)))) {
                int sign = 1;
                if (c == '-') { sign = -1; i++; }
                int val = 0;
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    val = val * 10 + (s.charAt(i) - '0');
                    i++;
                }
                list.add(sign * val);
            } else {
                i++;
            }
        }
        int[] a = new int[list.size()];
        for (int k = 0; k < a.length; k++) a[k] = list.get(k);
        return a;
    }

    static String readNonEmpty(BufferedReader br) throws Exception {
        String s = br.readLine();
        while (s != null && s.trim().isEmpty()) s = br.readLine();
        return s;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[] yTrue = parseInts(readNonEmpty(br));
        int[] yPred = parseInts(readNonEmpty(br));
        double beta = Double.parseDouble(readNonEmpty(br).trim());
        long tp = 0, fp = 0, fn = 0;
        int len = Math.min(yTrue.length, yPred.length);
        for (int i = 0; i < len; i++) {
            int actual = yTrue[i];
            int predicted = yPred[i];
            if (actual == 1 && predicted == 1) tp++;
            else if (actual == 0 && predicted == 1) fp++;
            else if (actual == 1 && predicted == 0) fn++;
        }
        double score;
        if (tp == 0) {
            score = 0.0;
        } else {
            double b2 = beta * beta;
            score = (1 + b2) * tp / ((1 + b2) * tp + b2 * fn + fp);
        }
        System.out.println(String.format(Locale.US, "%.3f", score));
    }
}

import java.io.*;
