import java.util.Random;

final class LoRALinear {
    private final double[][] baseWeight;
    private final double[] baseBias;
    private final double[][] a;
    private final double[][] b;
    private final double scale;

    LoRALinear(double[][] baseWeight, double[] baseBias, int rank, double alpha) {
        this.baseWeight = baseWeight;
        this.baseBias = baseBias;
        int inFeatures = baseWeight[0].length;
        int outFeatures = baseWeight.length;
        this.a = new double[rank][inFeatures];
        this.b = new double[outFeatures][rank];
        Random random = new Random();
        double bound = 1.0 / Math.sqrt(inFeatures);
        for (int i = 0; i < rank; i++) {
            for (int j = 0; j < inFeatures; j++) {
                a[i][j] = (random.nextDouble() * 2.0 - 1.0) * bound;
            }
        }
        this.scale = alpha / rank;
    }

    private static double[][] matmul(double[][] x, double[][] y) {
        int rows = x.length;
        int cols = y[0].length;
        int inner = y.length;
        double[][] out = new double[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                double sum = 0.0;
                for (int k = 0; k < inner; k++) {
                    sum += x[i][k] * y[k][j];
                }
                out[i][j] = sum;
            }
        }
        return out;
    }

    private static double[][] transpose(double[][] x) {
        int rows = x.length;
        int cols = x[0].length;
        double[][] out = new double[cols][rows];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out[j][i] = x[i][j];
            }
        }
        return out;
    }

    double[][] forward(double[][] inputs) {
        double[][] delta = matmul(matmul(inputs, transpose(a)), transpose(b));
        double[][] output = matmul(inputs, transpose(baseWeight));
        for (int i = 0; i < output.length; i++) {
            if (baseBias != null) {
                for (int j = 0; j < output[0].length; j++) {
                    output[i][j] += baseBias[j];
                }
            }
        }
        for (int i = 0; i < output.length; i++) {
            for (int j = 0; j < output[0].length; j++) {
                output[i][j] += scale * delta[i][j];
            }
        }
        return output;
    }

    public static void main(String[] args) {
        double[][] weight = {{1.0, 2.0}, {3.0, 4.0}};
        double[] bias = {0.5, -0.5};
        LoRALinear layer = new LoRALinear(weight, bias, 2, 1.0);
        double[][] out = layer.forward(new double[][]{{1.0, 1.0}});
        System.out.println(java.util.Arrays.deepToString(out));
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

final class CosineRetrieval {
    static double cosine(List<Double> left, List<Double> right) {
        double numerator = 0.0;
        int n = Math.min(left.size(), right.size());
        for (int i = 0; i < n; i++) {
            numerator += left.get(i) * right.get(i);
        }
        double leftNorm = 0.0;
        for (double value : left) {
            leftNorm += value * value;
        }
        double rightNorm = 0.0;
        for (double value : right) {
            rightNorm += value * value;
        }
        leftNorm = Math.sqrt(leftNorm);
        rightNorm = Math.sqrt(rightNorm);
        if (leftNorm == 0.0 || rightNorm == 0.0) {
            return 0.0;
        }
        return numerator / (leftNorm * rightNorm);
    }

    static final class Scored {
        final double score;
        final String docId;

        Scored(double score, String docId) {
            this.score = score;
            this.docId = docId;
        }
    }

    static List<Scored> topK(List<Double> query, List<Map.Entry<String, List<Double>>> documents, int k) {
        List<Scored> scored = new ArrayList<>();
        for (Map.Entry<String, List<Double>> document : documents) {
            scored.add(new Scored(cosine(query, document.getValue()), document.getKey()));
        }
        scored.sort((p, q) -> {
            int cmp = Double.compare(p.score, q.score);
            if (cmp != 0) {
                return -cmp;
            }
            return q.docId.compareTo(p.docId);
        });
        return new ArrayList<>(scored.subList(0, Math.min(k, scored.size())));
    }

    static List<Scored> topK(List<Double> query, List<Map.Entry<String, List<Double>>> documents) {
        return topK(query, documents, 3);
    }

    public static void main(String[] args) {
        List<Map.Entry<String, List<Double>>> documents = new ArrayList<>();
        documents.add(new java.util.AbstractMap.SimpleEntry<>("a", java.util.Arrays.asList(1.0, 0.0)));
        documents.add(new java.util.AbstractMap.SimpleEntry<>("b", java.util.Arrays.asList(0.0, 1.0)));
        List<Scored> top = topK(java.util.Arrays.asList(1.0, 0.1), documents, 3);
        for (Scored scored : top) {
            System.out.println(scored.docId + " " + scored.score);
        }
    }
}

