final class IdempotentExecutor {
    interface Function {
        Object apply(Map<String, Object> arguments) throws Exception;
    }

    private final Map<String, Object> results = new HashMap<>();

    Object execute(String callId, Function function, Map<String, Object> arguments) throws Exception {
        if (results.containsKey(callId)) {
            return results.get(callId);
        }
        Object result = function.apply(arguments);
        results.put(callId, result);
        return result;
    }

    Object execute(String callId, Function function) throws Exception {
        return execute(callId, function, new LinkedHashMap<>());
    }

    public static void main(String[] args) throws Exception {
        IdempotentExecutor executor = new IdempotentExecutor();
        Function function = arguments -> "result";
        System.out.println(executor.execute("call-1", function));
        System.out.println(executor.execute("call-1", function));
    }
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class SseParser {
    static List<Map<String, String>> parseSse(Iterable<String> lines) {
        List<Map<String, String>> events = new ArrayList<>();
        String eventType = "message";
        List<String> data = new ArrayList<>();
        for (String raw : lines) {
            String line = stripTrailingNewlines(raw);
            if (line.isEmpty()) {
                if (!data.isEmpty()) {
                    Map<String, String> event = new LinkedHashMap<>();
                    event.put("event", eventType);
                    event.put("data", String.join("\n", data));
                    events.add(event);
                }
                eventType = "message";
                data = new ArrayList<>();
            } else if (line.startsWith("event:")) {
                eventType = line.substring(6).trim();
            } else if (line.startsWith("data:")) {
                data.add(stripLeadingWhitespace(line.substring(5)));
            }
        }
        return events;
    }

    private static String stripTrailingNewlines(String value) {
        int end = value.length();
        while (end > 0 && value.charAt(end - 1) == '\n') {
            end--;
        }
        return value.substring(0, end);
    }

    private static String stripLeadingWhitespace(String value) {
        int start = 0;
        while (start < value.length() && Character.isWhitespace(value.charAt(start))) {
            start++;
        }
        return value.substring(start);
    }

    public static void main(String[] args) {
        List<String> lines = new ArrayList<>();
        lines.add("event: update");
        lines.add("data: hello");
        lines.add("data: world");
        lines.add("");
        System.out.println(parseSse(lines));
    }
}

