def matches(a, s):
    n = len(a)
    if len(s) != n:
        return False
    v2c = {}
    c2v = {}
    for i in range(n):
        v = a[i]
        c = s[i]
        if v in v2c:
            if v2c[v] != c:
                return False
        else:
            v2c[v] = c
        if c in c2v:
            if c2v[c] != v:
                return False
        else:
            c2v[c] = v
    return True

