import sys

server_services = {}
running_count = {}
deps = {}

def init():
    server_services.clear()
    running_count.clear()
    deps.clear()

def start_service(server_id, name):
    s = server_services.setdefault(server_id, set())
    if name in s:
        return False
    s.add(name)
    running_count[name] = running_count.get(name, 0) + 1
    return True

def reboot_servers(ids):
    for sid in ids:
        s = server_services.get(sid)
        if s is not None:
            for name in list(s):
                running_count[name] = running_count.get(name, 0) - 1
            s.clear()

def add_dependency(fr, to):
    s = deps.setdefault(fr, set())
    if to in s:
        return False
    s.add(to)
    return True

def avail(name, visiting):
    c = running_count.get(name, 0)
    if c <= 0:
        return False
    if name in visiting:
        return True
    visiting.add(name)
    ds = deps.get(name)
    if ds is not None:
        for d in ds:
            if not avail(d, visiting):
                return False
    visiting.discard(name)
    return True

def is_service_available(name):
    return avail(name, set())

def extract_quoted(s):
    a = s.index(chr(34))
    b = s.index(chr(34), a + 1)
    return s[a + 1:b]

def extract_quoted_list(s):
    res = []
    i = 0
    while True:
        a = s.find(chr(34), i)
        if a < 0:
            break
        b = s.find(chr(34), a + 1)
        if b < 0:
            break
        res.append(s[a + 1:b])
        i = b + 1
    return res

def main():
    out = []
    init()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line.startswith('ServiceWgSys'):
            init()
            out.append('null')
        elif line.startswith('rebootServers'):
            l = line.index('[')
            r = line.index(']')
            inside = line[l + 1:r].strip()
            ids = []
            if inside:
                ids = [int(x.strip()) for x in inside.split(',')]
            reboot_servers(ids)
            out.append('null')
        elif line.startswith('startService'):
            l = line.index('(')
            r = line.rindex(')')
            inside = line[l + 1:r]
            comma = inside.index(',')
            sid = int(inside[:comma].strip())
            name = extract_quoted(inside[comma + 1:])
