def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    ps = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        ps.append((x, y))
    if n < 2:
        print('0.0000')
        return
    ps.sort(key=lambda p: (p[0], p[1]))
    best = [float('inf')]

    def d2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def rec(l, r):
        if r - l <= 3:
            for i in range(l, r + 1):
                for j in range(i + 1, r + 1):
                    d = d2(ps[i], ps[j])
                    if d < best[0]:
                        best[0] = d
            ps[l:r + 1] = sorted(ps[l:r + 1], key=lambda p: p[1])
            return
        mid = (l + r) // 2
        midx = ps[mid][0]
        rec(l, mid)
        rec(mid + 1, r)
        strip = []
        for i in range(l, r + 1):
            dx = ps[i][0] - midx
            if dx * dx < best[0]:
                strip.append(ps[i])
        strip.sort(key=lambda p: p[1])
        for i in range(len(strip)):
            for j in range(i + 1, len(strip)):
                dy = strip[j][1] - strip[i][1]
                if dy * dy >= best[0]:
                    break
                d = d2(strip[i], strip[j])
                if d < best[0]:
                    best[0] = d
        merged = []
        i = l
        j = mid + 1
        while i <= mid and j <= r:
            if ps[i][1] <= ps[j][1]:
                merged.append(ps[i])
                i += 1
            else:
                merged.append(ps[j])
                j += 1
        while i <= mid:
            merged.append(ps[i])
            i += 1
        while j <= r:
            merged.append(ps[j])
            j += 1
        ps[l:r + 1] = merged

    rec(0, n - 1)
    print('%.4f' % math.sqrt(best[0]))

