import sys
import math

EPS = 1e-12

def parse_matrix(text, key):
    ki = text.find(key)
    if ki < 0:
        return None
    start = text.find('[', ki)
    if start < 0:
        return None
    depth = 0
    end = -1
    for i in range(start, len(text)):
        ch = text[i]
        if ch == '[':
            depth += 1
        elif ch == ']':
            depth -= 1
            if depth == 0:
                end = i
                break
    if end < 0:
        return None
    mat = text[start:end + 1]
    rows = []
    buf = ''
    inrow = False
    depth = 0
    for ch in mat:
        if ch == '[':
            depth += 1
            if depth == 2:
                inrow = True
                buf = ''
        elif ch == ']':
            if depth == 2:
                inrow = False
                inner = buf.strip()
                if inner:
                    rows.append([float(x.strip()) for x in inner.split(',')])
            depth -= 1
        else:
            if inrow:
                buf += ch
    return rows

def parse_int_list(text, key):
    ki = text.find(key)
    if ki < 0:
        return None
    start = text.find('[', ki)
    end = text.find(']', start)
    inner = text[start + 1:end].strip()
    if not inner:
        return []
    return [int(x.strip()) for x in inner.split(',')]

def dist2(a, b):
    s = 0.0
    for i in range(len(a)):
        d = a[i] - b[i]
        s += d * d
    return s

def nearest(x, centers):
    bi = 0
    bd = float('inf')
    for c in range(len(centers)):
        dd = dist2(x, centers[c])
        if dd < bd:
            bd = dd
            bi = c
    return bi

class JavaRandom:
    def __init__(self, seed):
        self.seed = (seed ^ 0x5DEECE66D) & ((1 << 48) - 1)
    def next(self, bits):
        self.seed = (self.seed * 0x5DEECE66D + 0xB) & ((1 << 48) - 1)
        return self.seed >> (48 - bits)
    def next_int(self, bound):
        if (bound & -bound) == bound:
            return (bound * self.next(31)) >> 31
        while True:
            bits = self.next(31)
            val = bits % bound
            if bits - val + (bound - 1) <= 0x7FFFFFFF:
                return val
    def next_double(self):
        return ((self.next(26) << 27) + self.next(27)) / float(1 << 53)

def eigen_sym(Ain, n):
    a = [row[:] for row in Ain]
    v = [[0.0] * n for _ in range(n)]
    for i in range(n):
        v[i][i] = 1.0
    for it in range(300):
        p = 0
        q = 1
        mx = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                t = abs(a[i][j])
                if t > mx:
                    mx = t
                    p = i
                    q = j
        if mx < 1e-13:
            break
        app = a[p][p]
        aqq = a[q][q]
        apq = a[p][q]
        theta = (aqq - app) / (2 * apq)
        if theta >= 0:
            tt = 1.0 / (theta + math.sqrt(1 + theta * theta))
        else:
            tt = -1.0 / (-theta + math.sqrt(1 + theta * theta))
        c = 1.0 / math.sqrt(1 + tt * tt)
        s = tt * c
        for i in range(n):
            aip = a[i][p]
            aiq = a[i][q]
            a[i][p] = c * aip - s * aiq
            a[i][q] = s * aip + c * aiq
        for i in range(n):
            api = a[p][i]
            aqi = a[q][i]
            a[p][i] = c * api - s * aqi
            a[q][i] = s * api + c * aqi
        for i in range(n):
            vip = v[i][p]
            viq = v[i][q]
            v[i][p] = c * vip - s * viq
            v[i][q] = s * vip + c * viq
    val = [a[i][i] for i in range(n)]
    order = sorted(range(n), key=lambda i: val[i], reverse=True)
    sv = [val[o] for o in order]
    svec = [[v[i][o] for o in order] for i in range(n)]
    return sv, svec

def kmeans(X, k):
    n = len(X)
    d = len(X[0])
    best = None
    best_inertia = float('inf')
    for run in range(10):
        rnd = JavaRandom(42 + run)
        cent = [[0.0] * d for _ in range(k)]
        first = rnd.next_int(n)
        cent[0] = X[first][:]
        dist = [dist2(X[i], cent[0]) for i in range(n)]
        for c in range(1, k):
            ssum = 0.0
            for vv in dist:
                ssum += vv
            if ssum <= EPS:
                idx = rnd.next_int(n)
            else:
                r = rnd.next_double() * ssum
                acc = 0.0
                idx = n - 1
                for i in range(n):
                    acc += dist[i]
                    if acc >= r:
                        idx = i
                        break
            cent[c] = X[idx][:]
            for i in range(n):
                dd = dist2(X[i], cent[c])
                if dd < dist[i]:
                    dist[i] = dd
        lab = [-1] * n
        for it in range(300):
            changed = False
            for i in range(n):
                nl = nearest(X[i], cent)
                if nl != lab[i]:
                    lab[i] = nl
                    changed = True
            nc = [[0.0] * d for _ in range(k)]
            cnt = [0] * k
            for i in range(n):
                l = lab[i]
                cnt[l] += 1
                for j in range(d):
                    nc[l][j] += X[i][j]
            for c in range(k):
                if cnt[c] > 0:
                    for j in range(d):
                        nc[c][j] /= cnt[c]
                else:
                    nc[c] = cent[c][:]
            cent = nc
            if not changed and it > 0:
                break
        inertia = 0.0
        for i in range(n):
            inertia += dist2(X[i], cent[lab[i]])
        if inertia < best_inertia:
            best_inertia = inertia
            best = {'centers': cent, 'labels': lab, 'k': k}
    return best

def reorder_centers(km):
    k = km['k']
    idx = list(range(k))
    idx.sort(key=lambda i: km['centers'][i][0], reverse=True)
    km['centers'] = [km['centers'][i] for i in idx]

def silhouette(X, lab, k):
    n = len(X)
    cnt = [0] * k
    for l in lab:
        cnt[l] += 1
    total = 0.0
    for i in range(n):
        li = lab[i]
        if cnt[li] <= 1:
            continue
        a = 0.0
        for j in range(n):
            if j != i and lab[j] == li:
                a += math.sqrt(dist2(X[i], X[j]))
        a /= (cnt[li] - 1)
        b = float('inf')
        for c in range(k):
            if c == li or cnt[c] == 0:
                continue
            s = 0.0
            for j in range(n):
                if lab[j] == c:
                    s += math.sqrt(dist2(X[i], X[j]))
            s /= cnt[c]
            if s < b:
                b = s
        den = max(a, b)
        if den == 0:
            total += float('nan')
        else:
            total += (b - a) / den
    return total / n

def main():
    sb = sys.stdin.read()
    train = parse_matrix(sb, 'TRAIN:')
    test = parse_matrix(sb, 'TEST:')
    klist = parse_int_list(sb, 'KLIST:')
    if train is None or test is None or klist is None:
        print('{}')
        return
    n = len(train)
    d = len(train[0])
    mt = len(test)
    mean = [0.0] * d
    for j in range(d):
        s = 0.0
        c = 0
        for i in range(n):
            if not math.isnan(train[i][j]):
                s += train[i][j]
                c += 1
        mean[j] = s / c if c > 0 else 0.0
        for i in range(n):
            if math.isnan(train[i][j]):
                train[i][j] = mean[j]
        for i in range(mt):
            if math.isnan(test[i][j]):
                test[i][j] = mean[j]
    for j in range(d):
        m = 0.0
        for i in range(n):
            m += train[i][j]
        m /= n
        v = 0.0
        for i in range(n):
            t = train[i][j] - m
            v += t * t
        v /= n
        sd = math.sqrt(v)
        if sd < EPS:
            sd = 1.0
        for i in range(n):
            train[i][j] = (train[i][j] - m) / sd
        for i in range(mt):
            test[i][j] = (test[i][j] - m) / sd
    cov = [[0.0] * d for _ in range(d)]
    for aa in range(d):
        for bb in range(d):
            s = 0.0
            for i in range(n):
                s += train[i][aa] * train[i][bb]
            cov[aa][bb] = s / max(1, n - 1)
    eig_val, eig_vec = eigen_sym(cov, d)
    total_v = 0.0
    for vv in eig_val:
        total_v += max(0.0, vv)
    pca_dim = d
    if total_v > EPS:
        cum = 0.0
        for k in range(d):
            cum += max(0.0, eig_val[k])
            if cum / total_v >= 0.95:
                pca_dim = k + 1
                break
    tr = [[0.0] * pca_dim for _ in range(n)]
    te = [[0.0] * pca_dim for _ in range(mt)]
    for k in range(pca_dim):
        for i in range(n):
            s = 0.0
            for j in range(d):
                s += train[i][j] * eig_vec[j][k]
            tr[i][k] = s
        for i in range(mt):
            s = 0.0
            for j in range(d):
                s += test[i][j] * eig_vec[j][k]
            te[i][k] = s
    best_k = -1
    best_score = float('-inf')
    for K in klist:
        if K < 1:
            continue
        if K == 1:
            if best_k == -1 or -1.0 > best_score:
                best_score = -1.0
                best_k = 1
            continue
        if K > n:
            continue
        km = kmeans(tr, K)
        sc = silhouette(tr, km['labels'], K)
        if sc > best_score + 1e-12 or (abs(sc - best_score) <= 1e-12 and (best_k == -1 or K < best_k)):
            best_score = sc
            best_k = K
    if best_k == -1:
        best_k = klist[0]
    km = kmeans(tr, best_k)
    reorder_centers(km)
    pred = [nearest(te[i], km['centers']) for i in range(mt)]
    pr = ', '.join(str(pp) for pp in pred)
    q = chr(34)
    print('{' + q + 'PCA_DIM' + q + ': ' + str(pca_dim) + ', ' + q + 'K_STAR' + q + ': ' + str(best_k) + ', ' + q + 'TEST_PRED' + q + ': [' + pr + ']}')

main()

