import sys
from collections import deque

sys.setrecursionlimit(1000000)

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        nR = int(next(it))
        mS = int(next(it))
        rpos = [int(next(it)) for _i in range(nR)]
        spos = [int(next(it)) for _i in range(mS)]
        scap = [int(next(it)) for _i in range(mS)]
        total_cap = 0
        for c in scap:
            total_cap += c
        if total_cap < nR:
            out.append('-1')
            continue

        def feasible(E):
            nodes = 1 + nR + mS + 1
            S = 0
            Tk = nodes - 1
            g = [[] for _ in range(nodes)]

            def add_edge(f, t, c):
                g[f].append([t, len(g[t]), c])
                g[t].append([f, len(g[f]) - 1, 0])

            for i in range(nR):
                add_edge(S, 1 + i, 1)
            for j in range(mS):
                add_edge(1 + nR + j, Tk, scap[j])
            for i in range(nR):
                for j in range(mS):
                    if abs(rpos[i] - spos[j]) <= E:
                        add_edge(1 + i, 1 + nR + j, 1)
            level = [-1] * nodes
            iter_ = [0] * nodes

            def bfs():
                for i in range(nodes):
                    level[i] = -1
                q = deque([S])
                level[S] = 0
                while q:
                    v = q.popleft()
                    for e in g[v]:
                        if e[2] > 0 and level[e[0]] < 0:
                            level[e[0]] = level[v] + 1
                            q.append(e[0])
                return level[Tk] >= 0

            def dfs(v, f):
                if v == Tk:
                    return f
                while iter_[v] < len(g[v]):
                    e = g[v][iter_[v]]
                    if e[2] > 0 and level[v] + 1 == level[e[0]]:
                        d = dfs(e[0], min(f, e[2]))
                        if d > 0:
                            e[2] -= d
                            g[e[0]][e[1]][2] += d
                            return d
                    iter_[v] += 1
                return 0

            flow = 0
            while bfs():
                for i in range(nodes):
                    iter_[i] = 0
                while True:
                    f = dfs(S, 1 << 60)
                    if f <= 0:
                        break
                    flow += f
                    if flow >= nR:
                        return True
            return flow == nR

        cand = set()
        cand.add(0)
        for i in range(nR):
            for j in range(mS):
                cand.add(abs(rpos[i] - spos[j]))
        lst = sorted(cand)
        lo = 0
        hi = len(lst) - 1
        ans_idx = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(lst[mid]):
                ans_idx = mid
                hi = mid - 1
            else:
                lo = mid + 1
        out.append(str(lst[ans_idx]) if ans_idx >= 0 else '-1')
    for v in out:
        print(v)

main()

