    if not data:
        return
    it = iter(data)
    N = int(next(it))
    start = [int(next(it)) for _ in range(N)]
    d = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            d[i][j] = int(next(it))
    full = 1 << N
    INF = 1 << 62
    dp = [[INF] * N for _ in range(full)]
    for i in range(N):
        if start[i] != -1:
            dp[1 << i][i] = start[i]
    for mask in range(1, full):
        for last in range(N):
            cur = dp[mask][last]
            if cur >= INF:
                continue
            for nxt in range(N):
                if mask & (1 << nxt):
                    continue
                if d[last][nxt] == -1:
                    continue
                nm = mask | (1 << nxt)
                cand = cur + d[last][nxt]
                if cand < dp[nm][nxt]:
                    dp[nm][nxt] = cand
    ans = INF
    for last in range(N):
        if dp[full - 1][last] < ans:
            ans = dp[full - 1][last]
    print(-1 if ans >= INF else ans)

